INSERT /* insertDrawHistory */
  INTO TB_RLT_DRAW_H (
       EVENT_ID
     , USR_ID
     , DRAW_RSLT_CD
     , WINNING_COUPON_NM
     , WINNING_COUPON_CD
     , DRAW_DTM
     , USE_YN
     , FST_REG_DTM
     , FST_REG_ID
     , LST_CHG_DTM
     , LST_CHG_ID
       )
VALUES (
       #{eventId}
     , #{usrId}
     , #{drawResultCode}
     , #{winningCouponName}
     , #{winningCouponCode}
     , NOW()
     , 'Y'
     , NOW()
     , #{regId}
     , NOW()
     , #{regId}
       )
